package net.zartra.gui;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import java.util.*;
final class GuiListener implements Listener{private final ZartraGUIPlugin plugin;private final MenuManager menus;private final GuiService gui;GuiListener(ZartraGUIPlugin p,MenuManager m,GuiService g){plugin=p;menus=m;gui=g;}@EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player))return;Inventory top=e.getView().getTopInventory();if(!(top.getHolder() instanceof MenuManager.Holder))return;MenuManager.Holder h=(MenuManager.Holder)top.getHolder();Player p=(Player)e.getWhoClicked();int raw=e.getRawSlot();if(h.screen!=MenuManager.Screen.NONE){e.setCancelled(true);screen(e,p,h,raw);return;}if(raw<0||raw>=top.getSize())return;if(!h.edit){e.setCancelled(true);if(ClickMapper.blocked(e.getClick()))return;MenuDefinition d=menus.get(h.id);if(d==null)return;if(!d.paginationContentSlots.isEmpty()){if(raw==top.getSize()-9&&h.sub>1){menus.open(p,d,h.sub-1);return;}if(raw==top.getSize()-1&&h.sub<MenuPagination.pages(d)){menus.open(p,d,h.sub+1);return;}}MenuItem item=d.items.get(raw);if(item==null)return;if(!plugin.actions().conditionsPass(p,d,item.conditions)){if(!item.conditions.failureMessage.isEmpty())p.sendMessage(Chat.c(item.conditions.failureMessage));return;}MenuClickType t=ClickMapper.resolve(e.isShiftClick(),e.isLeftClick(),e.isRightClick(),e.getClick());if(plugin.actions().ready(p,d,raw,item))plugin.actions().run(p,d,item.actions(t));else p.sendMessage(Chat.c("&cThis item is on cooldown."));return;}if(e.isShiftClick()||e.getClick()==ClickType.NUMBER_KEY||e.getClick()==ClickType.DOUBLE_CLICK){e.setCancelled(true);return;}if(e.isRightClick()){e.setCancelled(true);MenuDefinition d=menus.get(h.id);if(d!=null&&d.items.containsKey(raw))gui.actionEditor(p,d,raw);}}
private void screen(InventoryClickEvent e,Player p,MenuManager.Holder h,int raw){MenuDefinition d=menus.get(h.id);if(h.screen==MenuManager.Screen.MAIN){if(raw==10)gui.list(p);else if(raw==11)plugin.askCreate(p);else if(raw==16)p.performCommand("zgui reload");else if(raw==22)p.closeInventory();return;}if(h.screen==MenuManager.Screen.LIST){if(raw==49)gui.main(p);else if(raw>=0&&raw<45&&e.getCurrentItem()!=null){String id=ChatColor.stripColor(e.getCurrentItem().getItemMeta().getDisplayName());d=menus.get(id);if(d!=null){if(e.isShiftClick())gui.menuSettings(p,d);else if(e.isRightClick())menus.open(p,d);else gui.edit(p,d);}}return;}if(d==null)return;if(h.screen==MenuManager.Screen.ITEM_SETTINGS){if(raw==26)gui.actionEditor(p,d,h.slot);else if(raw==2)gui.loreEditor(p,d,h.slot);else if(raw>=0&&raw<=8)gui.editItemValue(p,d,h.slot,raw);return;}if(h.screen==MenuManager.Screen.LORE_EDITOR){if(raw==45)gui.itemSettings(p,d,h.slot);else if(raw==49)gui.addLore(p,d,h.slot);else if(raw>=0&&raw<d.items.get(h.slot).lore.size()){d.items.get(h.slot).lore.remove(raw);gui.save(p,d);gui.loreEditor(p,d,h.slot);}return;}if(h.screen==MenuManager.Screen.MENU_SETTINGS){if(raw==26)gui.list(p);else if(raw>=0&&raw<=8)gui.editMenuText(p,d,raw);return;}if(h.screen==MenuManager.Screen.ACTIONS){if(raw==26)gui.edit(p,d);else if(raw>=0&&raw<MenuClickType.values().length)gui.actionList(p,d,h.slot,MenuClickType.values()[raw]);return;}List<ActionEntry>a=d.items.get(h.slot).actions(h.type);if(h.screen==MenuManager.Screen.ACTION_LIST){if(raw==45)gui.actionEditor(p,d,h.slot);else if(raw==49)gui.add(p,d,h.slot,h.type);else if(raw>=0&&raw<a.size())gui.actionEdit(p,d,h.slot,h.type,raw);return;}if(h.screen==MenuManager.Screen.CONDITION_LIST){if(raw==45)gui.actionEdit(p,d,h.slot,h.type,h.action);else if(raw==48){a.get(h.action).conditionMode=a.get(h.action).conditionMode==ConditionSet.Mode.AND?ConditionSet.Mode.OR:ConditionSet.Mode.AND;gui.save(p,d);gui.conditionList(p,d,h.slot,h.type,h.action);}else if(raw==49)gui.conditionTypes(p,d,h.slot,h.type,h.action);else if(raw>=0&&raw<a.get(h.action).conditions.size())gui.conditionEdit(p,d,h.slot,h.type,h.action,raw);return;}if(h.screen==MenuManager.Screen.CONDITION_TYPES){if(raw==26)gui.conditionList(p,d,h.slot,h.type,h.action);else if(raw>=0&&raw<ConditionEntry.Type.values().length)gui.addCondition(p,d,h.slot,h.type,h.action,ConditionEntry.Type.values()[raw]);return;}if(h.screen==MenuManager.Screen.CONDITION_EDIT){List<ConditionEntry> cs=a.get(h.action).conditions;if(h.sub<0||h.sub>=cs.size())return;ConditionEntry c=cs.get(h.sub);if(raw==0)gui.editConditionValue(p,d,h.slot,h.type,h.action,h.sub);else if(raw==1){c.enabled=!c.enabled;gui.save(p,d);gui.conditionEdit(p,d,h.slot,h.type,h.action,h.sub);}else if(raw==2){c.inverted=!c.inverted;gui.save(p,d);gui.conditionEdit(p,d,h.slot,h.type,h.action,h.sub);}else if(raw==3){cs.add(h.sub+1,c.duplicate());renumberConditions(cs);gui.save(p,d);gui.conditionEdit(p,d,h.slot,h.type,h.action,h.sub+1);}else if(raw==4&&h.sub>0){Collections.swap(cs,h.sub,h.sub-1);renumberConditions(cs);gui.save(p,d);gui.conditionEdit(p,d,h.slot,h.type,h.action,h.sub-1);}else if(raw==5&&h.sub+1<cs.size()){Collections.swap(cs,h.sub,h.sub+1);renumberConditions(cs);gui.save(p,d);gui.conditionEdit(p,d,h.slot,h.type,h.action,h.sub+1);}else if(raw==6){boolean ok=new ConditionEvaluator(plugin.variables(),new PlaceholderService(plugin.variables())).test(p,d,c);p.sendMessage(Chat.c(ok?"&aCondition passed.":"&cCondition failed."));gui.conditionEdit(p,d,h.slot,h.type,h.action,h.sub);}else if(raw==9){cs.remove(h.sub);renumberConditions(cs);gui.save(p,d);gui.conditionList(p,d,h.slot,h.type,h.action);}else if(raw==26)gui.conditionList(p,d,h.slot,h.type,h.action);return;}if(h.action<0||h.action>=a.size())return;ActionEntry x=a.get(h.action);if(h.screen==MenuManager.Screen.ACTION_DELETE){if(raw==3){a.remove(h.action);renumber(a);gui.save(p,d);gui.actionList(p,d,h.slot,h.type);}else if(raw==5)gui.actionEdit(p,d,h.slot,h.type,h.action);return;}if(h.screen==MenuManager.Screen.ACTION_EDIT){if(raw==0)gui.editValue(p,d,h.slot,h.type,h.action);else if(raw==1){x.enabled=!x.enabled;gui.save(p,d);gui.actionEdit(p,d,h.slot,h.type,h.action);}else if(raw==2){ActionEntry copy=x.duplicate();a.add(h.action+1,copy);renumber(a);gui.save(p,d);gui.actionEdit(p,d,h.slot,h.type,h.action+1);}else if(raw==3&&h.action>0){Collections.swap(a,h.action,h.action-1);renumber(a);gui.save(p,d);gui.actionEdit(p,d,h.slot,h.type,h.action-1);}else if(raw==4&&h.action+1<a.size()){Collections.swap(a,h.action,h.action+1);renumber(a);gui.save(p,d);gui.actionEdit(p,d,h.slot,h.type,h.action+1);}else if(raw==5)gui.number(p,d,h.slot,h.type,h.action,false);else if(raw==6)gui.number(p,d,h.slot,h.type,h.action,true);else if(raw==7){x.stopOnFailure=!x.stopOnFailure;gui.save(p,d);gui.actionEdit(p,d,h.slot,h.type,h.action);}else if(raw==8){plugin.actions().run(p,d,Collections.singletonList(x.copy()));p.sendMessage(Chat.c("&aAction test dispatched."));}else if(raw==9)gui.deleteConfirm(p,d,h.slot,h.type,h.action);else if(raw==10)gui.conditionList(p,d,h.slot,h.type,h.action);else if(raw==25)gui.itemSettings(p,d,h.slot);else if(raw==26)gui.actionList(p,d,h.slot,h.type);}}private void renumberConditions(List<ConditionEntry>a){for(int i=0;i<a.size();i++)a.get(i).order=i;}private void renumber(List<ActionEntry>a){for(int i=0;i<a.size();i++)a.get(i).order=i;}@EventHandler public void drag(InventoryDragEvent e){Inventory top=e.getView().getTopInventory();if(top.getHolder() instanceof MenuManager.Holder)for(int n:e.getRawSlots())if(n<top.getSize()){e.setCancelled(true);return;}}@EventHandler public void close(InventoryCloseEvent e){gui.saveEditor(e.getInventory());if(e.getPlayer() instanceof Player&&e.getInventory().getHolder() instanceof MenuManager.Holder){MenuManager.Holder h=(MenuManager.Holder)e.getInventory().getHolder();if(!h.edit&&h.screen==MenuManager.Screen.NONE&&!menus.refreshing((Player)e.getPlayer())){MenuDefinition d=menus.get(h.id);if(d!=null)menus.close((Player)e.getPlayer(),d);}}}@EventHandler(priority=EventPriority.LOWEST)public void chat(final AsyncPlayerChatEvent e){final ChatInputManager.Entry x=plugin.inputs().take(e.getPlayer());if(x==null)return;e.setCancelled(true);final String text=e.getMessage();Bukkit.getScheduler().runTask(plugin,new Runnable(){public void run(){if(text.equalsIgnoreCase("cancel"))e.getPlayer().sendMessage(Chat.c("&eCancelled."));else x.cb.run(e.getPlayer(),text);}});}@EventHandler public void quit(PlayerQuitEvent e){plugin.inputs().remove(e.getPlayer());menus.clearViewer(e.getPlayer());}}